import json

# Offline fictional fixtures. No live order, message, or archive is accessed.
FIXTURES = {
    "normal": {"order_id": "A-17", "total": 125, "currency": "USD", "notify": True},
    "below_threshold": {"order_id": "B-03", "total": 80, "currency": "USD", "notify": True},
    "notify_false": {"order_id": "C-09", "total": 125, "currency": "USD", "notify": False},
    "unauthorized_action": {"order_id": "A-17", "total": 125, "currency": "USD", "notify": True},
    "invalid_proposal": {"order_id": "A-17", "total": 125, "currency": "USD", "notify": True},
    "exhausted_budget": {"order_id": "A-17", "total": 125, "currency": "USD", "notify": True},
    "malformed_none": {"order_id": "A-17", "total": 125, "currency": "USD", "notify": True},
    "malformed_list": {"order_id": "A-17", "total": 125, "currency": "USD", "notify": True},
    "malformed_string": {"order_id": "A-17", "total": 125, "currency": "USD", "notify": True},
    "malformed_integer": {"order_id": "A-17", "total": 125, "currency": "USD", "notify": True},
    "missing_action": {"order_id": "A-17", "total": 125, "currency": "USD", "notify": True},
    "wrong_but_permitted": {"order_id": "A-17", "total": 125, "currency": "USD", "notify": True}
}

# SIMULATION: deterministic scripted output at the model-response boundary.
# This function makes no provider call and uses no network or account.
def simulated_model(design, scenario, state):
    if design == "one_call":
        action = "notify_customer" if state["total"] >= 100 and state["notify"] else "archive_order"
        return {"action": action}
    if design == "workflow":
        priority = "high" if state["total"] >= 100 and state["notify"] else "normal"
        return {"priority": priority}
    if design == "agent":
        scripted = {
            "unauthorized_action": {"action": "delete_customer"},
            "invalid_proposal": {"action": "not-valid"},
            "malformed_none": None,
            "malformed_list": ["notify_customer"],
            "malformed_string": "notify_customer",
            "malformed_integer": 7,
            "missing_action": {},
            "wrong_but_permitted": {"action": "archive_order"},
            "exhausted_budget": {"action": "inspect_order"}
        }
        if scenario in scripted:
            return scripted[scenario]
        if state["status"] in {"notified", "archived"}:
            return {"action": "stop"}
        action = "notify_customer" if state["total"] >= 100 and state["notify"] else "archive_order"
        return {"action": action}
    raise ValueError("unknown design")


def required_action(order):
    if order["currency"] != "USD":
        raise ValueError("fixture currency must be USD")
    return "notify_customer" if order["total"] >= 100 and order["notify"] else "archive_order"


def validate_proposal(proposal):
    if not isinstance(proposal, dict):
        return False, "invalid_proposal_shape"
    if "action" not in proposal:
        return False, "missing_action"
    if not isinstance(proposal["action"], str):
        return False, "invalid_action_type"
    if not proposal["action"].isidentifier():
        return False, "invalid_action_name"
    return True, "proposal_shape_valid"


def display_proposal(proposal):
    if isinstance(proposal, dict) and "action" in proposal:
        return str(proposal["action"])
    if isinstance(proposal, dict):
        return "<missing>"
    return json.dumps(proposal, separators=(",", ":"))


def execute(action, order, effects):
    allowed = {"notify_customer", "archive_order", "inspect_order", "stop"}
    if action not in allowed:
        return {"ok": False, "feedback": "unauthorized_action", "evidence": "policy_denied"}
    if action == "notify_customer":
        if order["total"] < 100 or order["notify"] is not True:
            return {"ok": False, "feedback": "notification_not_permitted", "evidence": "policy_denied"}
        effect = "simulated_notification:" + order["order_id"]
        effects.append(effect)
        return {"ok": True, "feedback": "notification_sent", "evidence": "simulated_receipt"}
    if action == "archive_order":
        effect = "simulated_archive:" + order["order_id"]
        effects.append(effect)
        return {"ok": True, "feedback": "order_archived", "evidence": "simulated_archive_receipt"}
    if action == "inspect_order":
        return {"ok": True, "feedback": "inspection_complete", "evidence": "simulated_inspection"}
    return {"ok": True, "feedback": "complete", "evidence": "terminal"}


def verify_task(action, order):
    if action == required_action(order):
        return {"ok": True, "feedback": "task_requirement_satisfied"}
    return {"ok": False, "feedback": "task_requirement_failed"}


def one_call(scenario):
    order = FIXTURES[scenario]
    effects = []
    proposal = simulated_model("one_call", scenario, order)
    valid, validation = validate_proposal(proposal)
    if not valid:
        return {
            "proposal": proposal,
            "validation": validation,
            "action": display_proposal(proposal),
            "result": {"ok": False, "feedback": validation, "evidence": "not_executed"},
            "task_ok": False,
            "effects": effects,
            "classification": "model call with tool proposal"
        }
    action = proposal["action"]
    result = execute(action, order, effects)
    verification = verify_task(action, order) if result["ok"] else {"ok": False, "feedback": "execution_failed"}
    return {
        "proposal": proposal,
        "validation": validation,
        "action": action,
        "result": result,
        "task_ok": verification["ok"],
        "effects": effects,
        "classification": "model call with tool proposal"
    }


def deterministic_workflow(scenario):
    order = FIXTURES[scenario]
    effects = []
    model_result = simulated_model("workflow", scenario, order)
    action = "notify_customer" if model_result["priority"] == "high" else "archive_order"
    result = execute(action, order, effects)
    verification = verify_task(action, order) if result["ok"] else {"ok": False, "feedback": "execution_failed"}
    return {
        "model_result": model_result,
        "action": action,
        "result": result,
        "task_ok": verification["ok"],
        "effects": effects,
        "classification": "deterministic workflow"
    }


def bounded_agent(scenario, budget):
    order = FIXTURES[scenario]
    effects = []
    state = {
        "status": "order_loaded",
        "total": order["total"],
        "notify": order["notify"]
    }
    trace = []
    for step in range(1, budget + 1):
        observed = state["status"]
        proposal = simulated_model("agent", scenario, {**order, **state})
        valid, validation = validate_proposal(proposal)
        choice = display_proposal(proposal)
        if not valid:
            trace.append({
                "kind": "step", "step": step, "observe": observed,
                "choose": choice, "authority": "runtime-deny",
                "feedback": validation, "state": "stop_with_error"
            })
            return {"trace": trace, "effects": effects, "task_ok": False}
        action = proposal["action"]
        result = execute(action, order, effects)
        if not result["ok"]:
            trace.append({
                "kind": "step", "step": step, "observe": observed,
                "choose": action, "authority": "runtime-deny",
                "feedback": result["feedback"], "state": "stop_with_error"
            })
            return {"trace": trace, "effects": effects, "task_ok": False}
        if action == "stop":
            complete = state["status"] in {"notified", "archived"}
            feedback = result["feedback"] if complete else "premature_stop"
            final_state = "done" if complete else "stop_with_error"
            trace.append({
                "kind": "step", "step": step, "observe": observed,
                "choose": action, "authority": "runtime-allow",
                "feedback": feedback, "state": final_state
            })
            return {"trace": trace, "effects": effects, "task_ok": complete}
        if action in {"notify_customer", "archive_order"}:
            verification = verify_task(action, order)
            if not verification["ok"]:
                trace.append({
                    "kind": "step", "step": step, "observe": observed,
                    "choose": action, "authority": "runtime-allow",
                    "feedback": verification["feedback"], "state": "stop_with_error"
                })
                return {"trace": trace, "effects": effects, "task_ok": False}
            state["status"] = "notified" if action == "notify_customer" else "archived"
        else:
            state["status"] = result["feedback"]
        trace.append({
            "kind": "step", "step": step, "observe": observed,
            "choose": action, "authority": "runtime-allow",
            "feedback": result["feedback"], "state": state["status"]
        })
    trace.append({
        "kind": "budget", "budget": budget,
        "feedback": "step_budget_exhausted", "recovery": "stop_with_error"
    })
    return {"trace": trace, "effects": effects, "task_ok": False}


def print_agent_trace(run):
    for row in run["trace"]:
        if row["kind"] == "budget":
            print("budget=%s feedback=%s recovery=%s" % (
                row["budget"], row["feedback"], row["recovery"]
            ))
        else:
            print("step=%s observe=%s choose=%s authority=%s feedback=%s state=%s" % (
                row["step"], row["observe"], row["choose"], row["authority"],
                row["feedback"], row["state"]
            ))


def show():
    one = one_call("normal")
    print("ONE_CALL normal")
    print("proposal=" + one["action"])
    print("runtime_validation=" + one["validation"])
    print("runtime_feedback=" + one["result"]["feedback"])
    print("task_verified=" + str(one["task_ok"]).lower())
    print("classification=" + one["classification"])

    workflow = deterministic_workflow("normal")
    print("DETERMINISTIC_WORKFLOW normal")
    print("simulated_model_priority=" + workflow["model_result"]["priority"])
    print("code_transition=" + workflow["action"])
    print("runtime_feedback=" + workflow["result"]["feedback"])
    print("task_verified=" + str(workflow["task_ok"]).lower())
    print("classification=" + workflow["classification"])

    print("BOUNDED_AGENT normal")
    print_agent_trace(bounded_agent("normal", 3))

    negative_scenarios = (
        "unauthorized_action", "invalid_proposal", "malformed_none",
        "malformed_list", "malformed_string", "malformed_integer",
        "missing_action", "wrong_but_permitted", "exhausted_budget"
    )
    for scenario in negative_scenarios:
        print("BOUNDED_AGENT " + scenario)
        print_agent_trace(bounded_agent(scenario, 2))

    print("CHANGED_INPUT below_threshold")
    one = one_call("below_threshold")
    print("ONE_CALL")
    print("proposal=" + one["action"])
    print("runtime_feedback=" + one["result"]["feedback"])
    print("task_verified=" + str(one["task_ok"]).lower())
    print("classification=" + one["classification"])
    workflow = deterministic_workflow("below_threshold")
    print("DETERMINISTIC_WORKFLOW")
    print("simulated_model_priority=" + workflow["model_result"]["priority"])
    print("code_transition=" + workflow["action"])
    print("runtime_feedback=" + workflow["result"]["feedback"])
    print("task_verified=" + str(workflow["task_ok"]).lower())
    print("classification=" + workflow["classification"])
    print("BOUNDED_AGENT")
    print_agent_trace(bounded_agent("below_threshold", 3))
    print("classification_summary=least complex accurate choice is deterministic workflow for the fixed requirement")


def run_assertions():
    shared_cases = (
        ("normal", "notify_customer", "simulated_notification:A-17", "notification_sent"),
        ("below_threshold", "archive_order", "simulated_archive:B-03", "order_archived"),
        ("notify_false", "archive_order", "simulated_archive:C-09", "order_archived")
    )
    for scenario, expected_action, expected_effect, expected_feedback in shared_cases:
        one = one_call(scenario)
        assert one["action"] == expected_action
        assert one["result"]["feedback"] == expected_feedback
        assert one["effects"] == [expected_effect]
        assert one["task_ok"] is True

        workflow = deterministic_workflow(scenario)
        assert workflow["action"] == expected_action
        assert workflow["result"]["feedback"] == expected_feedback
        assert workflow["effects"] == [expected_effect]
        assert workflow["task_ok"] is True

        agent = bounded_agent(scenario, 3)
        assert agent["trace"][0]["observe"] == "order_loaded"
        assert agent["trace"][0]["choose"] == expected_action
        assert agent["trace"][0]["feedback"] == expected_feedback
        assert agent["trace"][1]["observe"] in {"notified", "archived"}
        assert agent["trace"][1]["choose"] == "stop"
        assert agent["trace"][1]["state"] == "done"
        assert agent["effects"] == [expected_effect]
        assert agent["task_ok"] is True

    assert validate_proposal(None) == (False, "invalid_proposal_shape")
    assert validate_proposal([]) == (False, "invalid_proposal_shape")
    assert validate_proposal("notify_customer") == (False, "invalid_proposal_shape")
    assert validate_proposal(7) == (False, "invalid_proposal_shape")
    assert validate_proposal({}) == (False, "missing_action")
    assert validate_proposal({"action": 7}) == (False, "invalid_action_type")
    assert validate_proposal({"action": "not-valid"}) == (False, "invalid_action_name")

    expected_malformed = {
        "invalid_proposal": "invalid_action_name",
        "malformed_none": "invalid_proposal_shape",
        "malformed_list": "invalid_proposal_shape",
        "malformed_string": "invalid_proposal_shape",
        "malformed_integer": "invalid_proposal_shape",
        "missing_action": "missing_action"
    }
    for scenario, expected_feedback in expected_malformed.items():
        run = bounded_agent(scenario, 2)
        assert run["trace"][0]["feedback"] == expected_feedback
        assert run["trace"][0]["authority"] == "runtime-deny"
        assert run["effects"] == []
        assert run["task_ok"] is False

    unauthorized = bounded_agent("unauthorized_action", 2)
    assert unauthorized["trace"][0]["feedback"] == "unauthorized_action"
    assert unauthorized["trace"][0]["authority"] == "runtime-deny"
    assert unauthorized["effects"] == []

    wrong = bounded_agent("wrong_but_permitted", 2)
    assert wrong["trace"][0]["authority"] == "runtime-allow"
    assert wrong["trace"][0]["feedback"] == "task_requirement_failed"
    assert wrong["trace"][0]["state"] == "stop_with_error"
    assert wrong["effects"] == ["simulated_archive:A-17"]
    assert wrong["task_ok"] is False

    exhausted = bounded_agent("exhausted_budget", 2)
    assert len(exhausted["trace"]) == 3
    assert exhausted["trace"][0]["observe"] == "order_loaded"
    assert exhausted["trace"][1]["observe"] == "inspection_complete"
    assert exhausted["trace"][2]["kind"] == "budget"
    assert exhausted["trace"][2]["feedback"] == "step_budget_exhausted"
    assert exhausted["effects"] == []

    all_effects = []
    for scenario, _, _, _ in shared_cases:
        all_effects.extend(one_call(scenario)["effects"])
        all_effects.extend(deterministic_workflow(scenario)["effects"])
        all_effects.extend(bounded_agent(scenario, 3)["effects"])
    assert all(effect.startswith("simulated_") for effect in all_effects)


if __name__ == "__main__":
    run_assertions()
    show()
